from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        # Pre‑compute powers of 4 (4^0, 4^1, …) up to a safe limit.
        pow4 = [1]
        while pow4[-1] <= 10**18:          # enough for all possible inputs
            pow4.append(pow4[-1] * 4)

        # sum_{x=1..n} floor(log_4(x))
        def sum_floor_log4(n: int) -> int:
            if n <= 0:
                return 0
            total = 0
            # k is the value of floor(log_4(x)) for the current interval.
            for k in range(len(pow4) - 1):
                start = pow4[k]                # 4^k
                if start > n:
                    break
                # Interval where floor(log_4(x)) = k is [4^k, 4^{k+1} - 1]
                end = min(n, pow4[k + 1] - 1)
                cnt = end - start + 1
                total += k * cnt
            return total

        # Total number of reductions needed for all numbers from 1 to n.
        # For each x we need floor(log_4(x)) + 1 operations on that element.
        def total_reductions(n: int) -> int:
            if n <= 0:
                return 0
            return n + sum_floor_log4(n)

        answer = 0
        for l, r in queries:
            # Sum of required reductions for the interval [l, r]
            total = total_reductions(r) - total_reductions(l - 1)
            # Each operation reduces two elements, so we need at least ceil(total / 2)
            answer += (total + 1) // 2
        return answer

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        # A number is beautiful if product of its digits is divisible by sum of its digits.
        # If a number contains a zero digit, product = 0, so it is always beautiful.
        # Therefore we only need to count non‑beautiful numbers that have no zero digit.
        # Let A(N) = count of numbers <= N with no zero digit.
        # Let B(N) = count of numbers <= N with no zero digit and product % sum == 0.
        # Then non‑beautiful numbers up to N are A(N) - B(N).
        # The answer for [l, r] is:
        #   (r - l + 1) - ( (A(r) - B(r)) - (A(l-1) - B(l-1)) )
        # We compute A(N) and B(N) using digit DP.

        from functools import lru_cache

        # ---------- count numbers <= N with no zero digit ----------
        def count_no_zero(N: int) -> int:
            if N <= 0:
                return 0
            s = str(N)
            digits = list(map(int, s))
            n = len(digits)

            @lru_cache(maxsize=None)
            def dp(pos: int, started: bool, tight: bool) -> int:
                if pos == n:
                    return 1 if started else 0
                limit = digits[pos] if tight else 9
                total = 0
                for d in range(0, limit + 1):
                    ntight = tight and (d == limit)
                    if not started:
                        if d == 0:
                            total += dp(pos + 1, False, ntight)
                        else:
                            # start with a non‑zero digit
                            total += dp(pos + 1, True, ntight)
                    else:
                        # already started, zero not allowed
                        if d == 0:
                            continue
                        total += dp(pos + 1, True, ntight)
                return total

            return dp(0, False, True)

        # ---------- count numbers <= N with no zero digit and product % sum == 0 ----------
        def count_beautiful_no_zero(N: int) -> int:
            if N <= 0:
                return 0
            digits = list(map(int, str(N)))
            n = len(digits)
            total_beautiful = 0

            # For each possible digit sum s (1..81) we count numbers with that sum
            # whose product is divisible by s.
            for target_sum in range(1, 82):
                @lru_cache(maxsize=None)
                def dp(pos: int, sum_sofar: int, mod_sofar: int,
                        started: bool, tight: bool) -> int:
                    if pos == n:
                        return 1 if (started and sum_sofar == target_sum
                                      and mod_sofar == 0) else 0

                    # Pruning: if we already exceed the target sum, stop.
                    if started and sum_sofar > target_sum:
                        return 0

                    # Pruning based on remaining positions
                    if started:
                        remaining = target_sum - sum_sofar
                        # each remaining digit is at least 1 and at most 9
                        if remaining < (n - pos) or remaining > 9 * (n - pos):
                            return 0
                    else:
                        # we may start later; maximum achievable sum is 9 * remaining positions
                        if 9 * (n - pos) < target_sum:
                            return 0

                    limit = digits[pos] if tight else 9
                    total = 0
                    for d in range(0, limit + 1):
                        ntight = tight and (d == limit)
                        if not started:
                            if d == 0:
                                # stay not started
                                total += dp(pos + 1, 0, 0, False, ntight)
                            else:
                                # start with digit d (non‑zero)
                                if d > target_sum:
                                    continue
                                new_mod = d % target_sum
                                total += dp(pos + 1, d, new_mod, True, ntight)
                        else:
                            # already started, zero not allowed
                            if d == 0:
                                continue
                            new_sum = sum_sofar + d
                            if new_sum > target_sum:
                                continue
                            new_mod = (mod_sofar * d) % target_sum
                            total += dp(pos + 1, new_sum, new_mod, True, ntight)
                    return total

                total_beautiful += dp(0, 0, 0, False, True)
            return total_beautiful

        # Helper to count non‑beautiful numbers with no zero digit up to N
        def count_non_beautiful_no_zero(N: int) -> int:
            return count_no_zero(N) - count_beautiful_no_zero(N)

        total_range = r - l + 1
        non_beautiful_r = count_non_beautiful_no_zero(r)
        non_beautiful_l_1 = count_non_beautiful_no_zero(l - 1)

        # Beautiful numbers = total numbers - non‑beautiful numbers
        ans = total_range - (non_beautiful_r - non_beautiful_l_1)
        return ans

import sys

def solve():
    sys.setrecursionlimit(1 << 25)
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N)]

    # prefix distinct counts: pref[i] = #distinct in A[0..i-1]
    pref = [0] * (N + 1)
    last_seen = [0] * (N + 1)          # values are in [1, N]
    for i in range(1, N + 1):
        v = A[i - 1]
        if last_seen[v] == 0:
            pref[i] = pref[i - 1] + 1
        else:
            pref[i] = pref[i - 1]
        last_seen[v] = i

    # suffix distinct counts: suffix[i] = #distinct in A[i..N-1]
    suffix = [0] * (N + 1)
    last_seen_suf = [0] * (N + 1)
    for i in range(N - 1, -1, -1):
        v = A[i]
        if last_seen_suf[v] == 0:
            suffix[i] = suffix[i + 1] + 1
        else:
            suffix[i] = suffix[i + 1]
        last_seen_suf[v] = i + 1

    # segment tree supporting range add and range max, plus point set
    INF_NEG = -10**9
    size = 1
    while size < N:
        size <<= 1
    tree = [INF_NEG] * (2 * size)
    lazy = [0] * (2 * size)

    def apply(node, val):
        tree[node] += val
        lazy[node] += val

    def push(node):
        v = lazy[node]
        if v:
            apply(node * 2, v)
            apply(node * 2 + 1, v)
            lazy[node] = 0

    def range_add(node, l, r, ql, qr, val):
        if ql <= l and r <= qr:
            apply(node, val)
            return
        push(node)
        mid = (l + r) // 2
        if ql <= mid:
            range_add(node * 2, l, mid, ql, qr, val)
        if qr > mid:
            range_add(node * 2 + 1, mid + 1, r, ql, qr, val)
        tree[node] = tree[node * 2] if tree[node * 2] > tree[node * 2 + 1] else tree[node * 2 + 1]

    def add(l, r, val):
        if l > r:
            return
        range_add(1, 0, size - 1, l, r, val)

    def point_set(node, l, r, pos, val):
        if l == r:
            tree[node] = val
            lazy[node] = 0
            return
        push(node)
        mid = (l + r) // 2
        if pos <= mid:
            point_set(node * 2, l, mid, pos, val)
        else:
            point_set(node * 2 + 1, mid + 1, r, pos, val)
        tree[node] = tree[node * 2] if tree[node * 2] > tree[node * 2 + 1] else tree[node * 2 + 1]

    def set_point(pos, val):
        point_set(1, 0, size - 1, pos, val)

    def range_max(node, l, r, ql, qr):
        if ql <= l and r <= qr:
            return tree[node]
        push(node)
        mid = (l + r) // 2
        res = INF_NEG
        if ql <= mid:
            v = range_max(node * 2, l, mid, ql, qr)
            if v > res:
                res = v
        if qr > mid:
            v = range_max(node * 2 + 1, mid + 1, r, ql, qr)
            if v > res:
                res = v
        return res

    def query_max(l, r):
        if l > r:
            return INF_NEG
        return range_max(1, 0, size - 1, l, r)

    # main computation
    last_occ = [0] * (N + 1)          # last occurrence (0‑based) of each value
    ans = 0
    for j in range(1, N - 1):        # j = end index of the middle subarray (0‑based)
        i = j - 1                     # possible end index of the first subarray
        # initialise the leaf for i with distinct count of the first subarray
        set_point(i, pref[i + 1])
        pos = last_occ[A[j]]
        L = pos
        R = j - 1
        if L <= R:
            add(L, R, 1)             # A[j] is new for all i >= previous occurrence
        best_mid = query_max(0, j - 1)
        cand = best_mid + suffix[j + 1]
        if cand > ans:
            ans = cand
        last_occ[A[j]] = j

    print(ans)

if __name__ == "__main__":
    solve()

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        # forced[pos] = char if a T‑constraint forces this position
        forced = [None] * L
        for i, ch in enumerate(str1):
            if ch == 'T':
                for j, c in enumerate(str2):
                    pos = i + j
                    if forced[pos] is not None and forced[pos] != c:
                        return ""          # contradictory T‑constraints
                    forced[pos] = c

        # f_satisfied[i] – whether the F‑constraint starting at i is already satisfied
        # f_remaining[i] – number of still free positions in that constraint
        f_satisfied = [False] * n
        f_remaining = [0] * n
        for i, ch in enumerate(str1):
            if ch == 'F':
                satisfied = False
                free = 0
                for j in range(m):
                    pos = i + j
                    if forced[pos] is not None:
                        if forced[pos] != str2[j]:
                            satisfied = True          # at least one forced mismatch
                    else:
                        free += 1
                f_satisfied[i] = satisfied
                f_remaining[i] = free
                if not satisfied and free == 0:
                    return ""          # no way to make this F‑constraint true

        # pre‑compute, for each position, which F‑constraints cover it
        constraints_at_pos = [[] for _ in range(L)]
        for i, ch in enumerate(str1):
            if ch == 'F':
                for offset in range(m):
                    pos = i + offset
                    constraints_at_pos[pos].append(i)   # store start index

        # build the answer, filling forced positions first
        w = [''] * L
        for pos in range(L):
            if forced[pos] is not None:
                w[pos] = forced[pos]

        # greedy construction from left to right
        for pos in range(L):
            if forced[pos] is not None:
                continue

            # try the smallest possible character
            for c in 'abcdefghijklmnopqrstuvwxyz':
                ok = True
                # check all F‑constraints that cover this position
                for s in constraints_at_pos[pos]:
                    if f_satisfied[s]:
                        continue
                    offset = pos - s
                    if c == str2[offset]:
                        # we would match this constraint, so we need another free spot
                        if f_remaining[s] <= 1:
                            ok = False
                            break
                    # if c != str2[offset] we would satisfy this constraint – always safe
                if ok:
                    w[pos] = c
                    # update the affected constraints
                    for s in constraints_at_pos[pos]:
                        if f_satisfied[s]:
                            continue
                        offset = pos - s
                        if c != str2[offset]:
                            f_satisfied[s] = True
                            f_remaining[s] = 0
                        else:
                            f_remaining[s] -= 1
                    break
            else:
                # no character can be placed – the instance is unsatisfiable
                return ""

        # all F‑constraints must be satisfied in the end
        for i, ch in enumerate(str1):
            if ch == 'F' and not f_satisfied[i]:
                return ""

        return ''.join(w)

class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        ans = 0

        # Digits 1, 2, 5: any prefix part works (d' = 1)
        for i, ch in enumerate(s):
            if ch in '125':
                ans += i + 1

        # Digit 4: need Y % 2 == 0, i.e., last digit of Y even
        for i, ch in enumerate(s):
            if ch == '4':
                if i == 0:
                    ans += 1
                else:
                    if s[i-1] in '02468':
                        ans += i + 1
                    else:
                        ans += 1

        # Digit 8: need Y % 4 == 0
        for i, ch in enumerate(s):
            if ch == '8':
                if i == 0:
                    ans += 1
                elif i == 1:
                    ans += 1  # l = i (empty Y)
                    if s[0] in '048':
                        ans += 1  # l = 0
                else:
                    ans += 1  # l = i (empty Y)
                    if s[i-1] in '048':
                        ans += 1  # l = i-1
                    two = (ord(s[i-2]) - 48) * 10 + (ord(s[i-1]) - 48)
                    if two % 4 == 0:
                        ans += i - 1  # all l <= i-2

        # Helper for moduli where 10 is invertible (3, 7, 9)
        def count_mod(m, digits, inv10):
            freq = [0] * m
            freq[0] = 1  # prefix of length 0
            T = 0
            inv_pow = 1  # inv10^0
            total = 0
            for ch in s:
                if ch in digits:
                    total += freq[T]
                digit = ord(ch) - 48
                inv_pow = (inv_pow * inv10) % m
                T = (T + digit * inv_pow) % m
                freq[T] += 1
            return total

        # Modulus 3: digits 3 and 6
        ans += count_mod(3, ('3', '6'), 1)
        # Modulus 7: digit 7
        ans += count_mod(7, ('7',), 5)
        # Modulus 9: digit 9
        ans += count_mod(9, ('9',), 1)

        return ans

import sys

def solve() -> None:
    MOD = 998244353
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    M = int(data[1])
    S = data[2].strip()
    s_idx = [ord(ch) - ord('a') for ch in S]

    size = 1 << N  # number of states (≤ 2^10 = 1024)

    # Pre‑compute dp array for each mask: dp[i] = LCS length between S[0:i) and current T
    dp_masks = [[0] * (N + 1) for _ in range(size)]
    for mask in range(size):
        arr = dp_masks[mask]
        for i in range(1, N + 1):
            arr[i] = arr[i - 1] + ((mask >> (i - 1)) & 1)

    # Pre‑compute transition for each state and each character
    trans = [[0] * 26 for _ in range(size)]
    for mask in range(size):
        old = dp_masks[mask]
        for c in range(26):
            new = [0] * (N + 1)
            for i in range(1, N + 1):
                val = old[i]
                if new[i - 1] > val:
                    val = new[i - 1]
                if s_idx[i - 1] == c and old[i - 1] + 1 > val:
                    val = old[i - 1] + 1
                new[i] = val
            new_mask = 0
            for i in range(1, N + 1):
                if new[i] > new[i - 1]:
                    new_mask |= (1 << (i - 1))
            trans[mask][c] = new_mask

    # DP over the length of the string
    cnt = [0] * size
    cnt[0] = 1  # empty string
    for _ in range(M):
        nxt = [0] * size
        for mask in range(size):
            cur = cnt[mask]
            if cur == 0:
                continue
            row = trans[mask]
            for c in range(26):
                nxt[row[c]] = (nxt[row[c]] + cur) % MOD
        cnt = nxt

    # Popcount for each mask
    popcnt = [0] * size
    for mask in range(size):
        popcnt[mask] = mask.bit_count() if hasattr(int, "bit_count") else bin(mask).count('1')

    ans = [0] * (N + 1)
    for mask in range(size):
        k = popcnt[mask]
        ans[k] = (ans[k] + cnt[mask]) % MOD

    print(' '.join(str(ans[i]) for i in range(N + 1)))

