sys.setrecursionlimit(10000)

def solve():
    input_data = sys.stdin.read().split()
    N = int(input_data[0])
    P = int(input_data[1])
    halfN = N // 2
    maxM = N * (N - 1) // 2

    # Precompute binomial coefficients modulo P up to maxM
    C = [[0] * (maxM + 1) for _ in range(maxM + 1)]
    for i in range(maxM + 1):
        C[i][0] = C[i][i] = 1 % P
        for j in range(1, i):
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % P

    # Precompute F[a] for a=1..N
    F = [[0] * (maxM + 1) for _ in range(N + 1)]
    for a in range(1, N + 1):
        intra = a * (a - 1) // 2
        for x in range(intra + 1):
            F[a][x] = C[intra][x]

    # Precompute B[a][b] for a=1..N, b=1..N
    B = [[[0] * (maxM + 1) for _ in range(N + 1)] for _ in range(N + 1)]
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            # Compute B[a][b][y] for y from b to a*b
            for y in range(b, a * b + 1):
                total = 0
                for j in range(0, b + 1):
                    if a * (b - j) >= y:
                        term = C[b][j] * C[a * (b - j)][y]
                        if j % 2 == 1:
                            term = -term
                        total += term
                B[a][b][y] = total % P

    # Precompute H[a][b] = convolution of G (B[a][b]) and F[b]
    H = [[[0] * (maxM + 1) for _ in range(N + 1)] for _ in range(N + 1)]
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            # Convolve B[a][b] and F[b], truncated to maxM
            res = [0] * (maxM + 1)
            for i in range(maxM + 1):
                if B[a][b][i] != 0:
                    for j in range(maxM + 1 - i):
                        if F[b][j] != 0:
                            res[i + j] = (res[i + j] + B[a][b][i] * F[b][j]) % P
            H[a][b] = res

    memo = {}

    def dfs(a_prev, i, e, r):
        if r == 0:
            if e == halfN:
                return [1] + [0] * maxM
            else:
                return [0] * (maxM + 1)
        key = (a_prev, i, e, r)
        if key in memo:
            return memo[key]
        res = [0] * (maxM + 1)
        s = N - r  # vertices placed so far
        o = s - e  # odd sum so far
        for a_next in range(1, r + 1):
            if i % 2 == 0:
                e_new = e
                o_new = o + a_next
            else:
                e_new = e + a_next
                o_new = o
            # Prune
            if e_new > halfN or o_new > halfN:
                continue
            r_rem = r - a_next
            # Check feasibility: even sum must be able to reach halfN
            if e_new + r_rem < halfN:
                continue
            if o_new + r_rem < halfN:
                continue
            child = dfs(a_next, i + 1, e_new, r_rem)
            Hpoly = H[a_prev][a_next]
            temp = [0] * (maxM + 1)
            for d in range(maxM + 1):
                if Hpoly[d] != 0:
                    hd = Hpoly[d]
                    for m in range(d, maxM + 1):
                        if child[m - d] != 0:
                            temp[m] = (temp[m] + hd * child[m - d]) % P
            for m in range(maxM + 1):
                res[m] = (res[m] + temp[m]) % P
        memo[key] = res
        return res

    total_poly = dfs(1, 0, 1, N - 1)
    # Output for M from N-1 to maxM
    output = []
    for M in range(N - 1, maxM + 1):
        output.append(str(total_poly[M] % P))
    print(' '.join(output))

solve()

import sys

def mat_mult(A, B, mod):
    N = len(A)
    C = [[0] * N for _ in range(N)]
    for i in range(N):
        Ai = A[i]
        Ci = C[i]
        for k in range(N):
            aik = Ai[k]
            if aik:
                Bk = B[k]
                for j in range(N):
                    Ci[j] = (Ci[j] + aik * Bk[j]) % mod
    return C

def mat_pow(mat, exp, mod):
    N = len(mat)
    # identity matrix
    res = [[0] * N for _ in range(N)]
    for i in range(N):
        res[i][i] = 1
    base = mat
    while exp > 0:
        if exp & 1:
            res = mat_mult(res, base, mod)
        base = mat_mult(base, base, mod)
        exp >>= 1
    return res

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    N = next(it)
    p = next(it)
    A = [[next(it) for _ in range(N)] for _ in range(N)]

    # count zero entries
    K = sum(1 for i in range(N) for j in range(N) if A[i][j] == 0)

    if p == 2:
        # replace zeros by 1 (the only non‑zero element)
        C = [[A[i][j] if A[i][j] != 0 else 1 for j in range(N)] for i in range(N)]
        M = mat_pow(C, 2, p)
        out = '\n'.join(' '.join(str(x % p) for x in row) for row in M)
        sys.stdout.write(out)
        return

    # p > 2
    M = mat_pow(A, p, p)

    Z = [[0] * N for _ in range(N)]

    # self‑loop zero entries (i,i) contribute to both row i and column i
    for i in range(N):
        if A[i][i] == 0:
            # constant edge after the self‑loops -> start at i, end at j
            for j in range(N):
                if A[i][j] != 0:
                    Z[i][j] = (Z[i][j] + A[i][j]) % p
            # constant edge before the self‑loops -> start at j, end at i
            for j in range(N):
                if A[j][i] != 0:
                    Z[j][i] = (Z[j][i] + A[j][i]) % p

    # for p = 3 there is an additional pattern: off‑diagonal zero used twice
    # with a constant edge returning to its source
    if p == 3:
        for u in range(N):
            for v in range(N):
                if u != v and A[u][v] == 0 and A[v][u] != 0:
                    Z[u][v] = (Z[u][v] + A[v][u]) % p

    sign = 1 if K % 2 == 0 else p - 1  # (-1)^K  (mod p)

    S = [[0] * N for _ in range(N)]
    for i in range(N):
        Mi = M[i]
        Zi = Z[i]
        Si = S[i]
        for j in range(N):
            Si[j] = (sign * (Mi[j] + Zi[j])) % p

    out = '\n'.join(' '.join(str(x) for x in row) for row in S)
    sys.stdout.write(out)

if __name__ == "__main__":
    solve()

from typing import List

class SegmentTree:
    def __init__(self, arr: List[int]):
        self.n = len(arr)
        self.size = 4 * self.n
        self.total = [0] * self.size
        self.best = [0] * self.size
        self.pref = [0] * self.size
        self.suff = [0] * self.size
        self._build(1, 0, self.n - 1, arr)

    def _build(self, node: int, l: int, r: int, arr: List[int]):
        if l == r:
            val = arr[l]
            self.total[node] = val
            self.best[node] = val
            self.pref[node] = val
            self.suff[node] = val
        else:
            mid = (l + r) // 2
            self._build(node * 2, l, mid, arr)
            self._build(node * 2 + 1, mid + 1, r, arr)
            self._pull(node)

    def _pull(self, node: int):
        left = node * 2
        right = node * 2 + 1
        self.total[node] = self.total[left] + self.total[right]
        self.pref[node] = max(self.pref[left], self.total[left] + self.pref[right])
        self.suff[node] = max(self.suff[right], self.total[right] + self.suff[left])
        self.best[node] = max(self.best[left], self.best[right], self.suff[left] + self.pref[right])

    def update(self, idx: int, val: int):
        self._update(1, 0, self.n - 1, idx, val)

    def _update(self, node: int, l: int, r: int, idx: int, val: int):
        if l == r:
            self.total[node] = val
            self.best[node] = val
            self.pref[node] = val
            self.suff[node] = val
        else:
            mid = (l + r) // 2
            if idx <= mid:
                self._update(node * 2, l, mid, idx, val)
            else:
                self._update(node * 2 + 1, mid + 1, r, idx, val)
            self._pull(node)

    def query_best(self) -> int:
        return self.best[1]


class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        # Map each value to its list of indices
        pos = {}
        for i, v in enumerate(nums):
            if v not in pos:
                pos[v] = []
            pos[v].append(i)

        # Find the largest and second largest distinct values
        max1 = -10**18
        max2 = -10**18
        for v in nums:
            if v > max1:
                max2 = max1
                max1 = v
            elif v < max1 and v > max2:
                max2 = v

        # Build segment tree on original array
        seg = SegmentTree(nums)
        original_max = seg.query_best()
        ans = original_max

        # Process each distinct value
        for x, indices in pos.items():
            if len(indices) == n:
                # Removing x would empty the array, not allowed
                continue

            # Set all occurrences of x to 0
            for idx in indices:
                seg.update(idx, 0)
            cur_max = seg.query_best()

            # Restore original values
            for idx in indices:
                seg.update(idx, nums[idx])

            # Determine the maximum element among values not equal to x
            if x == max1:
                max_other = max2
            else:
                max_other = max1

            # If the best subarray sum after setting x to 0 is positive, it is valid.
            # Otherwise (cur_max == 0), the best subarray must consist only of the removed x's,
            # and the true answer for this x is the maximum subarray sum of the remaining
            # (non‑x) elements, which is max_other (could be negative).
            true_f = cur_max if cur_max > 0 else max_other
            if true_f > ans:
                ans = true_f

        return ans

from typing import List

class DSU:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x: int) -> int:
        # path compression
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a: int, b: int) -> None:
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return
        if self.rank[ra] < self.rank[rb]:
            self.parent[ra] = rb
        elif self.rank[ra] > self.rank[rb]:
            self.parent[rb] = ra
        else:
            self.parent[rb] = ra
            self.rank[ra] += 1


class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        dsu = DSU(n)

        # Numbers larger than the threshold can never be connected to any other node
        isolated_large = sum(1 for v in nums if v > threshold)

        # For values <= threshold store the index (values are unique)
        pos = [-1] * (threshold + 1)
        for i, v in enumerate(nums):
            if v <= threshold:
                pos[v] = i

        # For each L (1..threshold) keep the first index that divides L.
        # Any other number dividing L will be united with this first one.
        first = [-1] * (threshold + 1)

        for i, v in enumerate(nums):
            if v > threshold:
                continue
            # iterate over all multiples of v not exceeding the threshold
            for L in range(v, threshold + 1, v):
                if first[L] == -1:
                    first[L] = i
                else:
                    dsu.union(i, first[L])

        # Count distinct DSU roots among the numbers that are <= threshold
        roots = set()
        for i, v in enumerate(nums):
            if v <= threshold:
                roots.add(dsu.find(i))

        # Total components = isolated large numbers + components among the rest
        return isolated_large + len(roots)
